/// CQL of [`reserve_stock`] (`ReserveStock`).
pub const RESERVE_STOCK_CQL: &str = "UPDATE inventory SET reserved = ? WHERE sku = ? IF stock >= ?";

/// Result of the conditional write [`reserve_stock`].
#[derive(Debug, Clone, PartialEq)]
pub struct ReserveStockOutcome {
    /// Whether the write was applied.
    pub applied: bool,
    /// Current value, reported by the database when `applied` is false.
    pub stock: ::std::option::Option<i32>,
}

#[derive(::scylla::DeserializeRow)]
struct ReserveStockApplied {
    #[scylla(rename = "[applied]")]
    applied: bool,
}

#[derive(::scylla::DeserializeRow)]
struct ReserveStockCurrent {
    #[scylla(rename = "[applied]")]
    applied: bool,
    stock: ::std::option::Option<i32>,
}

#[derive(::scylla::DeserializeRow)]
struct ReserveStockFull {
    #[scylla(rename = "[applied]")]
    applied: bool,
    sku: ::std::option::Option<::std::string::String>,
    stock: ::std::option::Option<i32>,
    reserved: ::std::option::Option<i32>,
}

/// Bind values of [`reserve_stock`], in the order of the bind markers.
#[derive(Debug, Clone, PartialEq)]
pub struct ReserveStockParams {
    /// `reserved`. `None` binds NULL (a delete marker), it does not leave the value unset.
    pub reserved: ::std::option::Option<i32>,
    /// `sku` (eq)
    pub sku: ::std::string::String,
    /// `IF stock` (gte)
    pub stock: i32,
}

async fn reserve_stock_with(session: &::scylla::client::session::Session, prepared: &::scylla::statement::prepared::PreparedStatement, params: ReserveStockParams) -> ::std::result::Result<ReserveStockOutcome, CqlcError> {
    let result = session.execute_unpaged(prepared, (&params.reserved, &params.sku, &params.stock,)).await.map_err(|e| CqlcError::new("ReserveStock", CqlcErrorKind::Execute, e))?;
    let rows = result.into_rows_result().map_err(|e| CqlcError::new("ReserveStock", CqlcErrorKind::Rows, e))?;
    let specs = rows.column_specs();
    if specs.len() <= 1 {
        let applied = rows.first_row::<ReserveStockApplied>().map_err(|e| CqlcError::new("ReserveStock", CqlcErrorKind::Deserialize, e))?;
        Ok(ReserveStockOutcome { applied: applied.applied, stock: None })
    } else if specs.iter().any(|c| c.name() == "sku") {
        let full = rows.first_row::<ReserveStockFull>().map_err(|e| CqlcError::new("ReserveStock", CqlcErrorKind::Deserialize, e))?;
        Ok(ReserveStockOutcome { applied: full.applied, stock: full.stock })
    } else {
        let current = rows.first_row::<ReserveStockCurrent>().map_err(|e| CqlcError::new("ReserveStock", CqlcErrorKind::Deserialize, e))?;
        Ok(ReserveStockOutcome { applied: current.applied, stock: current.stock })
    }
}

